#include "elit21/risk/RiskEngine.h"
namespace elit21 {Result<void> RiskEngine::approveOrder(const CustomerOrder&o)const{if(o.total_cad<=0)return Result<void>::failure("Total de commande invalide.");if(o.total_cad>config_.maximum_order_value_cad)return Result<void>::failure("Commande supérieure au seuil autonome.");if(o.lines.empty())return Result<void>::failure("Commande sans article.");for(auto&l:o.lines)if(l.quantity<=0||l.aliexpress_product_id.empty()||l.aliexpress_sku_id.empty())return Result<void>::failure("Ligne non mappée vers AliExpress.");return Result<void>::success();}Result<void> RiskEngine::approveSupplier(double s,double r,int o,int d,const SourcingConfig&c)const{if(s<c.minimum_seller_score)return Result<void>::failure("Score vendeur insuffisant.");if(r<c.minimum_product_rating)return Result<void>::failure("Note produit insuffisante.");if(o<c.minimum_orders)return Result<void>::failure("Historique de ventes insuffisant.");if(d>c.maximum_delivery_days)return Result<void>::failure("Délai vers le Canada trop long.");return Result<void>::success();}}
